CREATE TABLE users (id UUID PRIMARY KEY, email VARCHAR(320) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE venues (id UUID PRIMARY KEY, name VARCHAR(200) NOT NULL, address VARCHAR(500) NOT NULL, city VARCHAR(120) NOT NULL, capacity INTEGER NOT NULL CHECK (capacity > 0), created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE seats (id UUID PRIMARY KEY, venue_id UUID NOT NULL REFERENCES venues(id), section VARCHAR(80) NOT NULL, row_number VARCHAR(20) NOT NULL, seat_number VARCHAR(20) NOT NULL, seat_type VARCHAR(20) NOT NULL, CONSTRAINT uk_venue_seat UNIQUE (venue_id, section, row_number, seat_number));
CREATE TABLE events (id UUID PRIMARY KEY, name VARCHAR(250) NOT NULL, description VARCHAR(4000) NOT NULL, category VARCHAR(100) NOT NULL, start_date_time TIMESTAMPTZ NOT NULL, end_date_time TIMESTAMPTZ NOT NULL, venue_id UUID NOT NULL REFERENCES venues(id), organizer_id UUID NOT NULL REFERENCES users(id), status VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, CHECK (end_date_time > start_date_time));
CREATE TABLE event_seats (id UUID PRIMARY KEY, event_id UUID NOT NULL REFERENCES events(id), seat_id UUID NOT NULL REFERENCES seats(id), price NUMERIC(12,2) NOT NULL CHECK (price >= 0), status VARCHAR(20) NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT uk_event_seat UNIQUE (event_id, seat_id));
CREATE TABLE bookings (id UUID PRIMARY KEY, booking_reference VARCHAR(40) NOT NULL UNIQUE, user_id UUID NOT NULL REFERENCES users(id), event_id UUID NOT NULL REFERENCES events(id), status VARCHAR(20) NOT NULL, total_amount NUMERIC(12,2) NOT NULL CHECK (total_amount >= 0), currency CHAR(3) NOT NULL, expires_at TIMESTAMPTZ NOT NULL, idempotency_key VARCHAR(100) NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE booking_items (id UUID PRIMARY KEY, booking_id UUID NOT NULL REFERENCES bookings(id), event_seat_id UUID NOT NULL REFERENCES event_seats(id), unit_price NUMERIC(12,2) NOT NULL, CONSTRAINT uk_booking_event_seat UNIQUE (booking_id, event_seat_id));
CREATE TABLE payments (id UUID PRIMARY KEY, booking_id UUID NOT NULL UNIQUE REFERENCES bookings(id), payment_reference VARCHAR(100) NOT NULL UNIQUE, amount NUMERIC(12,2) NOT NULL, currency CHAR(3) NOT NULL, status VARCHAR(20) NOT NULL, provider VARCHAR(50) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE tickets (id UUID PRIMARY KEY, ticket_number VARCHAR(60) NOT NULL UNIQUE, booking_id UUID NOT NULL REFERENCES bookings(id), event_seat_id UUID NOT NULL UNIQUE REFERENCES event_seats(id), qr_token VARCHAR(128) NOT NULL UNIQUE, status VARCHAR(20) NOT NULL, issued_at TIMESTAMPTZ NOT NULL, used_at TIMESTAMPTZ);
CREATE TABLE refresh_tokens (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE);
CREATE INDEX idx_events_start ON events(start_date_time);
CREATE INDEX idx_events_status ON events(status);
CREATE INDEX idx_bookings_user ON bookings(user_id);
CREATE INDEX idx_bookings_event ON bookings(event_id);
CREATE INDEX idx_event_seats_event_status ON event_seats(event_id, status);
CREATE INDEX idx_refresh_tokens_user ON refresh_tokens(user_id);
